head.script:
scwin.designTpCd;
scwin.gLdMktTp = js_market;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.getParentValue();
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37306.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        $c.frame.path("../").txb_isur_cd.setValue(dts_List.getCellData(row, "ISUR_CD")); // 부모창 회사코드
        $c.frame.path("../").txb_com_nm.setValue(dts_List.getCellData(row, "COM_ABBRV")); // 부모창 회사명
        $c.frame.path("../").txb_dtec_dd.setValue(dts_List.getCellData(row, "DTEC_DD")); // 부모창 적출일자
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37306.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_List.errorMsg) {
            await $c.win.alert(dts_List.errorMsg);
        } else {
            $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37306.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37306.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name img_Close_onclick
 * @description img_Close 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37306.img_Close_onclick" });
    }
};

/**
 * @method
 * @name img_Search_onclick
 * @description img_Search 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37306.img_Search_onclick" });
    }
};

/**
 * @method
 * @name txb_Search_onkeypress
 * @description txb_Search onkeypress 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_Search_onkeypress = async function() {
    try {
        if (window.event.keyCode === 13) {
            await scwin.search();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37306.txb_Search_onkeypress" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    const vCOM_NM = txb_Search.getValue();
    url += "&COM_NM=" + vCOM_NM;
    url += "&DESIGN_EXCLUDE_TP_CD=" + scwin.designTpCd; // 지정:1, 해제:2
    url += "&LD_MKT_TP_CD=" + scwin.gLdMktTp; // 시장구분
    url += "&SCREN_ID=" + "ULDSTF37306.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/ByPass.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParentValue
 * @description 부모창에서 필요변수 저장
 * @returns {void}
 * @hidden N
 */
scwin.getParentValue = function() {
    scwin.designTpCd = frame.opener.scwin.designTpCd;
};
